from lib import *
import re
R = J('d96')
def L(k): return [l for l in R[k].splitlines() if l.strip()]
pen = L('penetration'); bk = L('breakdown'); av = L('avalanche')
n = lambda l: int(re.search(r'数据库调用\s*(\d+)\s*次', l).group(1))
peak = lambda l: int(re.search(r'最高调用数 (\d+)', l).group(1))
tot = lambda l: int(re.search(r'共 (\d+) 次', l).group(1))
steps = [
    step(f"缓存穿透:请求的数据本来就不存在。不缓存空结果时,对同一个不存在的 key 请求 100 次 → 数据库调用 {n(pen[0])} 次;把「空」也缓存(短 TTL 10 秒)→ {n(pen[1])} 次。但如果攻击者每次用不同的 key({n(pen[2])} 个不同 key),空值缓存挡不住,仍是 {n(pen[2])} 次——这要靠参数校验、布隆过滤器之类(本文没有测)。", b=bars([['不缓存空结果', n(pen[0]), str(n(pen[0]))], ['缓存空结果', n(pen[1]), str(n(pen[1]))], ['100 个不同的 key', n(pen[2]), str(n(pen[2]))]], 100, mark=[0, 2], done=[1]), kv=KV([['同一个不存在的 key', f"{n(pen[0])} → {n(pen[1])} 次"], ['随机 key', '缓存空值无效']], ['同一个不存在的 key'])),
    step(f"缓存击穿:一个热点 key 刚过期,50 个并发请求同时回源:无保护 → 数据库调用 {n(bk[0])} 次;用 cache.add 做互斥锁(只有拿到锁的线程去数据库,其它线程短暂等待再读缓存)→ {n(bk[1])} 次,代价是最慢的请求略增(62 ms vs 55 ms,包含等待)。", b=bars([['无保护(数据库调用)', n(bk[0]), str(n(bk[0]))], ['互斥锁(数据库调用)', n(bk[1]), str(n(bk[1]))]], 50, mark=[0], done=[1]), kv=KV([['无保护', f"{n(bk[0])} 次"], ['互斥锁', f"{n(bk[1])} 次"]], ['互斥锁'])),
    step(f"缓存雪崩:300 个 key 相同 TTL(1.5 秒)同一时刻写入,40 个线程持续读 4 秒:数据库调用出现明显的脉冲——某个 250 ms 窗口最高 {peak(av[0])} 次,其它窗口是 0(窗口序列:0…11, 189, 147, 30, 0, 0, 0, 128, 163, 148, 22);TTL 加 ±1 秒随机抖动后,调用摊成平稳的每窗口约 100 次,最高 {peak(av[1])} 次(峰值降了 {100 - peak(av[1]) * 100 // peak(av[0])}%)。注意:抖动的总调用数反而更多({tot(av[1])} vs {tot(av[0])},因为抖动让一部分 key 的 TTL 更短,更频繁地过期)。", b=bars([['相同 TTL 峰值(次/250ms)', peak(av[0]), str(peak(av[0]))], ['抖动 TTL 峰值(次/250ms)', peak(av[1]), str(peak(av[1]))]], peak(av[0]) * 1.1, mark=[0], done=[1]), kv=KV([['相同 TTL', f"峰值 {peak(av[0])},有空闲窗口"], ['抖动', f"峰值 {peak(av[1])},平稳"]], ['抖动'])),
    step("这三个问题的共同点是「缓存没命中时,数据库承担了本不该有的负载」,防线分别是:①空值也缓存(穿透);②热点回源加互斥或提前刷新(击穿,第 97 篇的 stale-while-revalidate);③TTL 加随机抖动、预热(雪崩)。本实验是单进程内的线程模拟(LocMem + sleep 50 ms 当作数据库),表明机制,不代表真实数据库的绝对数字。", kv=KV([['防线', '缓存空值 / 互斥或提前刷新 / TTL 抖动']], ['防线'])),
]
A = dict(
    n=96, series='django', tags='Django,缓存,穿透,击穿,雪崩,真实验证,动画演示',
    desc=f'用线程 + 模拟数据库做缓存实验:穿透(同一不存在 key 100 次 {n(pen[0])} → {n(pen[1])} 次数据库调用,随机 key 仍 {n(pen[2])} 次);击穿(50 并发 {n(bk[0])} → {n(bk[1])} 次);雪崩(相同 TTL 250ms 窗口峰值 {peak(av[0])},TTL 抖动后 {peak(av[1])},但总调用数更多)。',
    lead='缓存穿透、击穿、雪崩这三个词几乎人人听过,但它们各自的量级是多少?常见的防线真的有效吗?这篇用 LocMem + 线程 + 一个睡 50 ms 的「数据库」把三种情形各做一遍,数出数据库被调用了多少次。',
    facts=[(f'{n(pen[0])} → {n(pen[1])}', '同一个不存在的 key 请求 100 次:不缓存空结果 → 缓存空结果的数据库调用次数'), (f'{n(bk[0])} → {n(bk[1])}', '热点 key 过期时 50 个并发请求:无保护 → cache.add 互斥锁的数据库调用次数'), (f'{peak(av[0])} → {peak(av[1])}', '雪崩:相同 TTL vs TTL 抖动,250 ms 窗口内的数据库调用峰值')],
    body=[
        sec('穿透', '', term('', blk('d96', 1)), '<p>「请求的 key 数据库里也没有」,所以缓存永远填不上。缓存空值(短 TTL)能挡住重复请求同一个不存在的 key;但随机 key 每个都是第一次,只能靠参数校验、布隆过滤器等前置手段。</p>'),
        sec('击穿', '', term('', blk('d96', 2)), '<p>互斥锁的写法:<code>cache.add(lock, 1, 5)</code> 成功者去回源,失败者轮询缓存。注意给锁设过期时间,防止拿锁的线程崩溃后锁永不释放;并发极高时轮询本身也有开销(本文没有测)。</p>'),
        sec('雪崩', '', term('', blk('d96', 3)), '<p>相同 TTL 的 key 同时批量写入(比如启动时预热),会同时过期。抖动能把脉冲摊平(峰值下降),但不减少总量;真实系统里还要配合限流、降级(本文没有做)。</p>'),
        sec('分步演示:三种缓存问题', '', demo('穿透 / 击穿 / 雪崩', [('b', 'bars', '数据库调用'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_D + '。LocMemCache + 线程;「数据库」是睡 50 ms 的函数;雪崩实验 40 线程、300 个 key、4 秒', '没有验证:Redis / Memcached 上的同类现象、多进程多机器下的互斥锁(需要分布式锁)、布隆过滤器、请求合并(singleflight)、缓存预热策略'],
)
